package com.quizmaster.dao;
import com.quizmaster.model.*;import com.quizmaster.util.*;import java.sql.*;import java.util.*;
public class QuestionDAO {
 private Question map(ResultSet r)throws SQLException{return new Question(r.getLong("question_id"),r.getLong("quiz_id"),r.getString("question_text"),r.getString("option_a"),r.getString("option_b"),r.getString("option_c"),r.getString("option_d"),r.getString("correct_option"),r.getInt("marks"));}
 public List<Question> list(long quiz,boolean shuffled)throws SQLException{List<Question> out=new ArrayList<>();try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("SELECT * FROM questions WHERE quiz_id=? ORDER BY question_id")){p.setLong(1,quiz);try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}if(shuffled)Collections.shuffle(out,new java.security.SecureRandom());return out;}
 public Question get(long id)throws SQLException{try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("SELECT * FROM questions WHERE question_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 public void save(long id,long quiz,String text,String a,String b,String optC,String d,String correct,int marks)throws SQLException{boolean edit=id>0;String sql=edit?"UPDATE questions SET question_text=?,option_a=?,option_b=?,option_c=?,option_d=?,correct_option=?,marks=? WHERE question_id=? AND quiz_id=?":"INSERT INTO questions(question_text,option_a,option_b,option_c,option_d,correct_option,marks,quiz_id) VALUES(?,?,?,?,?,?,?,?)";try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,text);p.setString(2,a);p.setString(3,b);p.setString(4,optC);p.setString(5,d);p.setString(6,correct);p.setInt(7,marks);p.setLong(8,edit?id:quiz);if(edit)p.setLong(9,quiz);p.executeUpdate();}}
 public void delete(long id,long quiz)throws SQLException{try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("DELETE FROM questions WHERE question_id=? AND quiz_id=?")){p.setLong(1,id);p.setLong(2,quiz);p.executeUpdate();}}
}
